select public.register_portal_session('Order fixture');
do $$ declare b uuid;br uuid;i uuid;r uuid;batch uuid;c uuid;o uuid;s uuid;creq uuid:=gen_random_uuid();oreq uuid:=gen_random_uuid();dreq uuid:=gen_random_uuid();due date:=(statement_timestamp() at time zone 'America/Lima')::date+1;items jsonb;begin
 b:=public.create_initial_bakery('Order bakery','Main');select id into br from public.branches where bakery_id=b;
 insert into public.ingredients(bakery_id,name,unit,reference_cost) values(b,'Harina','kg',2) returning id into i;
 perform public.record_stock_movement(b,br,i,gen_random_uuid(),'in',10,'Initial');
 r:=public.create_recipe_version(b,'Pan',100,jsonb_build_array(jsonb_build_object('ingredient_id',i,'quantity',2)));
 batch:=public.complete_production(b,br,r,gen_random_uuid(),100);
 perform public.set_recipe_price(b,r,1.5);
 perform public.set_catalog_product(b,r,'Pan francés','Panes','PAN-001',true);
 if not exists(select 1 from public.catalog_products where recipe_id=r and display_name='Pan francés' and unit_price=1.5) then raise exception 'Catalog missing';end if;
 c:=public.create_customer(b,creq,'Cliente prueba',null,null);
 if c<>public.create_customer(b,creq,'Cliente prueba',null,null) then raise exception 'Duplicate customer';end if;
 items:=jsonb_build_array(jsonb_build_object('recipe_id',r,'units',10));
 o:=public.create_customer_order(b,br,c,oreq,due,'Encargo',items);
 if o<>public.create_customer_order(b,br,c,oreq,due,'Encargo',items) then raise exception 'Duplicate order';end if;
 if (select total from public.customer_orders where id=o)<>15 then raise exception 'Order total';end if;
 if (select available_units from public.finished_stock where batch_id=batch)<>100 then raise exception 'Order reserved stock';end if;
 begin perform public.deliver_customer_order(b,o,dreq,'cash');raise exception 'Premature delivery';exception when invalid_parameter_value then null;end;
 perform public.set_order_status(b,o,'confirmed');perform public.set_order_status(b,o,'ready');
 perform public.open_cash_shift(b,br,gen_random_uuid(),0);
 perform public.set_catalog_product(b,r,'Pan francés','Panes','PAN-001',false);
 begin perform public.record_sale(b,br,gen_random_uuid(),'cash',jsonb_build_array(jsonb_build_object('batch_id',batch,'units',1,'unit_price',1.5)));raise exception 'Inactive product sold';exception when check_violation then null;end;
 begin perform public.deliver_customer_order(b,o,dreq,'cash');raise exception 'Inactive order delivered';exception when check_violation then null;end;
 perform public.set_catalog_product(b,r,'Pan francés','Panes','PAN-001',true);
 perform public.set_recipe_price(b,r,2);
 begin perform public.deliver_customer_order(b,o,dreq,'cash');raise exception 'Changed price accepted';exception when check_violation then null;end;
 perform public.set_recipe_price(b,r,1.5);
 s:=public.deliver_customer_order(b,o,dreq,'cash');
 if s<>public.deliver_customer_order(b,o,dreq,'cash') then raise exception 'Duplicate delivery';end if;
 if not exists(select 1 from public.customer_orders where id=o and sale_id=s and status='delivered') or (select available_units from public.finished_stock where batch_id=batch)<>90 or (select count(*) from public.sales where bakery_id=b)<>1 then raise exception 'Wrong delivery';end if;
 begin perform public.set_order_status(b,o,'cancelled');raise exception 'Delivered cancelled';exception when invalid_parameter_value then null;end;
 perform set_config('test.bakery',b::text,true);perform set_config('test.order',o::text,true);
end $$;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claim.session_id','30000000-0000-4000-8000-000000000002',true);
