do $$ begin
 if exists(select 1 from public.customers) or exists(select 1 from public.customer_orders) or exists(select 1 from public.catalog_products) then raise exception 'Tenant leak';end if;
 begin perform public.deliver_customer_order(current_setting('test.bakery')::uuid,current_setting('test.order')::uuid,gen_random_uuid(),'cash');raise exception 'Unauthorized delivery';exception when insufficient_privilege then null;end;
end $$;
rollback;
